<template>
  <div class="admin-page"><div class="container-wide admin-head"><div><span class="eyebrow">JINGHUI OPERATIONS</span><h1 class="serif">镜绘运营台</h1><p>管理定制履约、创作进度与签约画师档案。</p></div><div class="admin-user"><span class="live-dot"></span>运营后台 · {{ auth.user?.nickname }}</div></div>
    <div class="container-wide admin-tabs"><button v-for="t in tabs" :key="t.value" :class="{active:tab===t.value}" @click="tab=t.value"><el-icon><component :is="t.icon"/></el-icon>{{ t.label }}</button><button class="btn btn-primary btn-sm new-artist" @click="openArtist()"><el-icon><Plus /></el-icon>新增画师</button></div>
    <div class="container-wide admin-content">
      <template v-if="tab==='overview'"><div class="stats-grid"><div v-for="card in statCards" :key="card.label" class="stat-card"><div><span>{{ card.label }}</span><el-icon><component :is="card.icon"/></el-icon></div><strong>{{ card.value }}<small>{{ card.unit }}</small></strong><p>{{ card.note }}</p></div></div>
        <div class="overview-grid"><section class="dashboard-card"><div class="card-head"><h2 class="serif">订单履约分布</h2><button @click="tab='orders'">管理订单<el-icon><ArrowRight /></el-icon></button></div><div class="status-chart"><div v-for="item in statusChart" :key="item.status" class="chart-row"><span>{{ item.label }}</span><div><i :style="{width:item.percent}"></i></div><strong>{{ item.count }}</strong></div></div></section><section class="dashboard-card"><div class="card-head"><h2 class="serif">热门创作风格</h2><span>生成次数</span></div><div class="popular-list"><div v-for="(tpl,i) in stats?.popular_templates||[]" :key="tpl.id"><span class="rank">0{{ Number(i)+1 }}</span><strong>{{ tpl.name }}</strong><div><i :style="{width:popularPercent(tpl.uses)}"></i></div><span>{{ tpl.uses }}</span></div></div></section></div>
        <section class="dashboard-card recent-card"><div class="card-head"><h2 class="serif">最近定制订单</h2><button @click="loadAll"><el-icon><Refresh /></el-icon>刷新数据</button></div><OrderTable :orders="stats?.recent_orders||[]" @progress="openProgress" @status="openStatus" /></section>
      </template>
      <template v-else-if="tab==='orders'"><div class="list-toolbar"><div><h2 class="serif">定制订单管理</h2><p>状态流转将自动写入订单流水，并同步给用户。</p></div><el-select v-model="statusFilter" clearable placeholder="全部状态" style="width:150px" @change="loadOrders"><el-option v-for="(v,k) in statusMap" :key="k" :value="k" :label="v.label"/></el-select></div><section class="dashboard-card"><OrderTable :orders="orders" @progress="openProgress" @status="openStatus" /></section></template>
      <template v-else><div class="list-toolbar"><div><h2 class="serif">签约画师档案</h2><p>画师联系方式仅运营可见，一期由平台统一代录创作进度。</p></div><button class="btn btn-primary btn-sm" @click="openArtist()"><el-icon><Plus /></el-icon>新增画师</button></div><div class="artist-admin-grid"><article v-for="artist in artists" :key="artist.id" class="artist-admin-card"><div class="artist-admin-top"><img :src="mediaUrl(artist.avatar)" alt="画师头像"/><div><h3 class="serif">{{ artist.pen_name }}</h3><span>{{ formatSpecialties(artist.specialties) }}</span></div><span class="artist-status" :class="{inactive:artist.status!=='ACTIVE'}">{{ artist.status==='ACTIVE'?'合作中':'已暂停' }}</span></div><p>{{ artist.intro }}</p><dl><div><dt>从业年限</dt><dd>{{ artist.years_experience }} 年</dd></div><div><dt>用户评分</dt><dd>{{ artist.rating }} / 5.0</dd></div><div><dt>联系方式</dt><dd>{{ artist.contact||'未填写' }}</dd></div></dl><button class="btn btn-outline btn-sm" @click="openArtist(artist)"><el-icon><EditPen /></el-icon>编辑档案</button></article></div></template>
    </div>
    <el-dialog v-model="statusDialog" title="更新订单状态" width="min(480px,92vw)"><div v-if="currentOrder" class="dialog-order"><img :src="mediaUrl(currentOrder.media_asset?.url)" alt="订单形象"/><div><strong>{{ currentOrder.order_no }}</strong><span>{{ currentOrder.product?.name }} · 当前 {{ statusLabel(currentOrder.status) }}</span></div></div><el-form label-position="top"><el-form-item label="流转至"><el-select v-model="statusForm.status" style="width:100%"><el-option v-for="s in allowedStatuses" :key="s" :value="s" :label="statusLabel(s)"/></el-select></el-form-item><el-form-item label="进度说明"><el-input v-model="statusForm.note" type="textarea" :rows="3" placeholder="例如：画师已接单，开始准备宣纸与矿物颜料"/></el-form-item><el-form-item v-if="statusForm.status==='ASSIGNED'" label="关联画师"><el-select v-model="statusForm.artist_id" style="width:100%"><el-option v-for="a in artists" :key="a.id" :value="a.id" :label="a.pen_name"/></el-select></el-form-item><el-form-item v-if="statusForm.status==='SHIPPED'" label="物流单号"><el-input v-model="statusForm.tracking_no" placeholder="请输入物流单号"/></el-form-item></el-form><template #footer><button class="btn btn-outline" @click="statusDialog=false">取消</button><button class="btn btn-primary" :disabled="saving" @click="saveStatus">确认更新</button></template></el-dialog>
    <el-dialog v-model="progressDialog" title="代录创作进度" width="min(560px,94vw)"><div v-if="currentOrder" class="dialog-order"><img :src="mediaUrl(currentOrder.media_asset?.url)" alt="订单形象"/><div><strong>{{ currentOrder.order_no }}</strong><span>{{ currentOrder.product?.name }} · {{ statusLabel(currentOrder.status) }}</span></div></div><el-form label-position="top"><el-form-item label="创作节点"><el-input v-model="progressForm.step_name" placeholder="例如：罩染 · 色彩定型"/></el-form-item><el-form-item label="进度说明"><el-input v-model="progressForm.content" type="textarea" :rows="4" placeholder="用一段话向用户描述画师的创作细节与下一步安排"/></el-form-item><el-form-item label="实拍素材 URL"><el-input v-model="progressForm.media_urls" placeholder="/static/generated/seed_progress_01.svg"/><div class="field-help">演示可使用 /static/generated/seed_progress_01.svg；多个 URL 以英文逗号分隔</div></el-form-item></el-form><template #footer><button class="btn btn-outline" @click="progressDialog=false">取消</button><button class="btn btn-primary" :disabled="saving" @click="saveProgress"><el-icon><Promotion /></el-icon>发布给用户</button></template></el-dialog>
    <el-dialog v-model="artistDialog" :title="artistForm.id?'编辑画师档案':'新增签约画师'" width="min(600px,94vw)"><el-form label-position="top" class="artist-form"><div class="form-two"><el-form-item label="画师署名"><el-input v-model="artistForm.pen_name"/></el-form-item><el-form-item label="真实姓名（仅后台可见）"><el-input v-model="artistForm.real_name"/></el-form-item></div><div class="form-two"><el-form-item label="联系方式"><el-input v-model="artistForm.contact"/></el-form-item><el-form-item label="从业年限"><el-input-number v-model="artistForm.years_experience" :min="0" :max="80" style="width:100%"/></el-form-item></div><el-form-item label="擅长画种（逗号分隔）"><el-input v-model="artistForm.specialtiesText" placeholder="工笔, 国画"/></el-form-item><el-form-item label="画师简介"><el-input v-model="artistForm.intro" type="textarea" :rows="4"/></el-form-item><el-form-item label="头像 URL（选填）"><el-input v-model="artistForm.avatar"/></el-form-item></el-form><template #footer><button class="btn btn-outline" @click="artistDialog=false">取消</button><button class="btn btn-primary" :disabled="saving" @click="saveArtist">保存档案</button></template></el-dialog>
  </div>
</template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue';import { ElMessage } from 'element-plus';import { adminApi, mediaUrl } from '@/services/api';import { useAuthStore } from '@/stores/auth';import { statusLabel, statusMap } from '@/utils/format';import OrderTable from '@/components/OrderTable.vue'
const auth=useAuthStore(),tab=ref('overview'),stats=ref<any>(null),orders=ref<any[]>([]),artists=ref<any[]>([]),statusFilter=ref(''),saving=ref(false),statusDialog=ref(false),progressDialog=ref(false),artistDialog=ref(false),currentOrder=ref<any>(null)
const tabs=[{value:'overview',label:'经营概览',icon:'DataAnalysis'},{value:'orders',label:'订单与进度',icon:'Tickets'},{value:'artists',label:'画师档案',icon:'User'}]
const statusForm=reactive({status:'',note:'',artist_id:undefined as number|undefined,tracking_no:''});const progressForm=reactive({step_name:'',content:'',media_urls:'/static/generated/seed_progress_01.svg'});const artistForm=reactive<any>({id:null,pen_name:'',real_name:'',contact:'',years_experience:5,specialtiesText:'',intro:'',avatar:''})
const statCards=computed(()=>[{label:'累计定制订单',value:stats.value?.orders||0,unit:'单',icon:'Tickets',note:'全流程状态留痕可溯'},{label:'AI 生成任务',value:stats.value?.generation_tasks||0,unit:'次',icon:'MagicStick',note:`成功生成 ${stats.value?.generated_assets||0} 幅形象`},{label:'平台注册用户',value:stats.value?.users||0,unit:'人',icon:'User',note:'不含运营账号'},{label:'定制订单金额',value:Number(stats.value?.revenue||0).toLocaleString(),unit:'元',icon:'Wallet',note:'演示环境模拟支付数据'}])
const statusChart=computed(()=>{const rows=stats.value?.orders_by_status||{};const max=Math.max(1,...Object.values(rows).map(Number));return Object.entries(rows).map(([status,count])=>({status,label:statusLabel(status),count:Number(count),percent:(Number(count)/max*100)+'%'}))})
const allowedStatuses=computed(()=>stats.value?.allowed_transitions?.[currentOrder.value?.status]||[])
onMounted(loadAll)
async function loadAll(){try{const [s,a,o]=await Promise.all([adminApi.stats(),adminApi.artists(),adminApi.orders()]);stats.value=s;artists.value=a;orders.value=o}catch(e:any){ElMessage.error(e.message)}}
async function loadOrders(){orders.value=await adminApi.orders()}
function popularPercent(uses:number){const max=Math.max(1,...(stats.value?.popular_templates||[]).map((t:any)=>t.uses));return (uses/max*100)+'%'}
function formatSpecialties(s:any){return Array.isArray(s)?s.join(' · '):s}
function openStatus(order:any){currentOrder.value=order;statusForm.status='';statusForm.note='';statusForm.artist_id=order.artist_id;statusForm.tracking_no='';statusDialog.value=true}
function openProgress(order:any){currentOrder.value=order;progressForm.step_name='';progressForm.content='';progressForm.media_urls='/static/generated/seed_progress_01.svg';progressDialog.value=true}
async function saveStatus(){if(!statusForm.status){ElMessage.warning('请选择目标状态');return}saving.value=true;try{await adminApi.updateStatus(currentOrder.value.id,statusForm.status,statusForm.note);ElMessage.success('订单状态已更新');statusDialog.value=false;await loadAll()}catch(e:any){ElMessage.error(e.message)}finally{saving.value=false}}
async function saveProgress(){if(!progressForm.step_name||!progressForm.content){ElMessage.warning('请填写创作节点与说明');return}saving.value=true;try{await adminApi.addProgress(currentOrder.value.id,{step_name:progressForm.step_name,content:progressForm.content,media_urls:progressForm.media_urls.split(',').map(s=>s.trim()).filter(Boolean)});ElMessage.success('创作进度已同步给用户');progressDialog.value=false;await loadAll()}catch(e:any){ElMessage.error(e.message)}finally{saving.value=false}}
function openArtist(a?:any){Object.assign(artistForm,a?{...a,specialtiesText:formatSpecialties(a.specialties).replaceAll(' · ',',')}:{id:null,pen_name:'',real_name:'',contact:'',years_experience:5,specialtiesText:'',intro:'',avatar:''});artistDialog.value=true}
async function saveArtist(){saving.value=true;try{const data={...artistForm,specialties:artistForm.specialtiesText.split(/[,，]/).map((s:string)=>s.trim()).filter(Boolean),rating:5,commission_rate:.6,representative_urls:[]};delete data.specialtiesText;if(!data.id)delete data.id;await adminApi.saveArtist(data,data.id);ElMessage.success('画师档案已保存');artistDialog.value=false;await loadAll()}catch(e:any){ElMessage.error(e.message)}finally{saving.value=false}}

</script>
<style scoped>
