px;height:55px;object-fit:cover}.dialog-order strong{display:block;font-size:11px}.dialog-order span{display:block;font-size:9px;color:var(--muted);margin-top:5px}.field-help{font-size:8px;color:var(--muted);margin-top:6px}.form-two{display:grid;grid-template-columns:1fr 1fr;gap:15px}
:deep(.order-table-wrap){overflow-x:auto}:deep(.order-table){width:100%;border-collapse:collapse;font-size:10px}:deep(.order-table th){text-align:left;color:var(--muted);font-weight:400;font-size:8px;background:var(--paper);padding:10px}:deep(.order-table td){padding:12px 10px;border-bottom:1px solid var(--line);vertical-align:middle}:deep(.order-table td>strong){display:block;font-size:9px;font-weight:500}:deep(.order-table td>span){display:block;font-size:8px;color:var(--muted);margin-top:4px}:deep(.table-product){display:flex;align-items:center;gap:10px;min-width:190px}:deep(.table-product img){width:40px;height:46px;object-fit:cover}:deep(.table-product strong){display:block;font-size:10px;font-weight:500}:deep(.table-product span){display:block;font-size:8px;color:var(--muted);margin-top:4px}:deep(.table-price){color:var(--cinnabar);font-family:var(--serif);font-size:14px}:deep(.table-status){display:inline-block!important;background:rgba(169,75,60,.07);color:var(--cinnabar)!important;padding:5px 8px;margin:0!important;white-space:nowrap}:deep(.table-actions){white-space:nowrap}:deep(.table-actions button){border:0;background:none;color:var(--azure);font-size:9px;padding:4px}:deep(.table-actions button:hover){color:var(--cinnabar)}
